# owner: platform
"""Lay students out in rows of seats, ordered by name."""

from typing import List
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _sort_key(student: Student):
    last = student.last_name.lower()
    return (last, student.first_name.lower())

def _format_row(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"

def _chunks(items: list, size: int) -> List[list]:
    return [
        items[i:i + size]
        for i in range(0, len(items), size)
    ]

def _check(students, per_row: int) -> None:
    if per_row <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")

# ---
def seat_rows(students, per_row: int) -> List[str]:
    """One line of text per row, sorted by last name."""
    _check(students, per_row)
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, per_row)
    numbered = enumerate(rows, 1)
    return [_format_row(n, r) for n, r in numbered]

