# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _student(last, first):
    return Student("id", last, first, "A")

class SeatRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            _student("Halloway", "Juno"),
            _student("Dunmere", "Piet"),
            _student("Adler", "Sam")
        ]

    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seat_rows(self.students, 2),
            [
                "Row 1: Adler, Sam | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_row_when_seats_exceed_students(self):
        rows = seat_rows(self.students, 10)
        self.assertEqual(len(rows), 1)

    def test_same_last_name_sorts_by_first(self):
        pair = [
            _student("Lee", "Zed"),
            _student("Lee", "Al")
        ]
        self.assertEqual(
            seat_rows(pair, 2),
            ["Row 1: Lee, Al | Lee, Zed"]
        )

    def test_zero_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows(self.students, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
